// Package mockrt is the runtime shared by every mock that mock_gen
// generates. Generated code declares the typed parts of a mock (Param and
// Return structs, the interface methods, ReturnAll/ReturnCustom and the
// per-return setters) and delegates everything else here: the call log,
// the cross-method timeline, sticky/Once/Always/When stubs, Reset, the
// pending-stub accounting and, for --async mocks, the locking.
//
// The package is versioned together with the generator: a mock generated by
// mock_gen vX needs mockrt from the same module version. Test code reaches
// these types through the generated mock's Calls()/On() namespaces and
// rarely needs to name them directly.
package mockrt

import (
	"strconv"
	"sync"
	"unicode"
	"unicode/utf8"
)

// Mock is the state shared by every method of one generated mock: the
// global call counter and the cross-method timeline. The zero value is ready
// to use, so &XMock{} works without a constructor.
type Mock struct {
	global   int
	timeline []TimelineEntry
}

// Ref binds an operation to the mock it runs against. Generated code builds
// one per operation. Mu is the mock's lock, nil unless the mock was
// generated with --async; Name and Method only feed panic and error
// messages and the timeline.
type Ref struct {
	Mock   *Mock
	Mu     *sync.Mutex
	Name   string
	Method string
}

func (r Ref) lock() {
	if r.Mu != nil {
		r.Mu.Lock()
	}
}

func (r Ref) unlock() {
	if r.Mu != nil {
		r.Mu.Unlock()
	}
}

// index resolves At(i)-style indexes: negative i counts from the end;
// out-of-range i panics with a message that surfaces both the original
// input and the log length.
func (r Ref) index(length, i int) int {
	resolved := i
	if resolved < 0 {
		resolved += length
	}
	if resolved < 0 || resolved >= length {
		if i < 0 {
			panic(r.Name + " call index " + strconv.Itoa(i) + " (resolved to " + strconv.Itoa(resolved) + ") out of range, log has " + strconv.Itoa(length) + " entries")
		}
		panic(r.Name + " call index " + strconv.Itoa(i) + " out of range, log has " + strconv.Itoa(length) + " entries")
	}
	return resolved
}

// helperName is the name predicate panics use for the inspection helper,
// e.g. "serviceMockCallsHelper" for ServiceMock.
func (r Ref) helperName() string {
	first, size := utf8.DecodeRuneInString(r.Name)
	return string(unicode.ToLower(first)) + r.Name[size:] + "CallsHelper"
}

// Call is satisfied by every generated per-method Call struct and by
// TimelineEntry, so calls to different methods can be compared with
// HappenedBefore and AssertOrder.
type Call interface {
	Global() int
}

// TimelineEntry records one call across any method in invocation order.
// Method names the source method; Index is the per-method position at the
// time the call was recorded; GlobalIndex is monotonically increasing
// across all methods.
type TimelineEntry struct {
	Method      string
	Index       int
	GlobalIndex int
}

// Global returns the global ordering position for this entry.
func (e TimelineEntry) Global() int { return e.GlobalIndex }

// HappenedBefore returns true iff this entry was recorded before other.
func (e TimelineEntry) HappenedBefore(other Call) bool {
	return e.GlobalIndex < other.Global()
}

// T is the interface Verify and AssertOrder accept. *testing.T satisfies it.
type T interface {
	Helper()
	Errorf(format string, args ...any)
}
